export function allProps(obj: any, opt: string = 'tvp', depth = 6): GenObj | [] | string | boolean {
  try {
    if (!isObject(obj)) {
      return typeOf(obj);
    }
    if (depth-- < 0) {
      return 'END';
    }
    let opts = [...opt];
    let filter = !opts.includes('f');
    let res = isParsed(obj);
    if (res) {
      return {
        val: res, type: typeOf(res), parsed: res,
      };
    }
    let tstKeys = [];
    for (let prop of keepProps) {
      let val: any;
      try {
        val = obj[prop];
        if (val === undefined) {
          continue;
        }
        tstKeys.push(prop);
      } catch (e) {
        // Don't need to catch it
      }
    }

    let objProps = getProps(obj);
    if (filter) {
      objProps = filterProps(<string[]>objProps);
    }

    let unique = uniqueVals(objProps, tstKeys);
    if (isEmpty(intersect(opts, ['t', 'v', 'p',]))) { //Just the array of props
      return unique;
    } //We want more...

    let retObj: GenObj = {};
    for (let prop of unique) {
      let ret: GenObj = {};
      let val: any;
      try {
        val = obj[prop];
      } catch (e) {
        retObj[prop] = { error: `allProps`, depth, prop, opt };
        continue;
      }
      if (['prototype', 'constructor'].includes(prop)) {
        let bi: any;
        if (bi = isBuiltIn(val)) {
          ret.val = bi;
          retObj[prop] = ret;
          continue;
        }
      }
      if (opts.includes('v')) {
        ret.val = val;
      }
      if (opts.includes('t')) {
        ret.type = typeOf(val);
      }
      if (opts.includes('p') && isParsable(val)) {
        ret.parsed = allProps(val, opt, depth);
      }
      retObj[prop] = ret;
    }
    return retObj;
  } catch (e) {
    return `Exception in allProps at depth [${depth}] w. msg: [${e}]`;
  }
}
